import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"UGC 仿真风","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"prompts/ugc-style.md","filePath":"prompts/ugc-style.md","lastUpdated":1786327499000}'),o={name:"prompts/ugc-style.md"};function l(i,t,h,s,c,n){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="ugc-仿真风" tabindex="-1">UGC 仿真风 <a class="header-anchor" href="#ugc-仿真风" aria-label="Permalink to &quot;UGC 仿真风&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">待补充</p><p>这一页还没有实战 Prompt。下面是已确定的框架和一条必须守住的原则。</p></div><h2 id="这一页要解决的问题" tabindex="-1">这一页要解决的问题 <a class="header-anchor" href="#这一页要解决的问题" aria-label="Permalink to &quot;这一页要解决的问题&quot;">​</a></h2><p>信息流里，「看起来像广告」的内容会被直接划走，「看起来像真人分享」的内容完读率高得多。所以有一类需求是：<strong>让 AI 生成的素材看起来不像专业制作的</strong>。</p><p>这和其他所有场景的方向是<strong>相反的</strong>——别处在追求质感，这里在主动破坏质感。</p><h2 id="一条必须守住的原则" tabindex="-1">一条必须守住的原则 <a class="header-anchor" href="#一条必须守住的原则" aria-label="Permalink to &quot;一条必须守住的原则&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">仿真不等于伪装</p><p>做成 UGC 的<strong>视觉风格</strong>是创意手法，但不能让观众<strong>误以为这是真实用户的自发分享</strong>。</p><p>具体来说：</p><ul><li>平台对广告内容有强制标识要求，该标的必须标</li><li>不能虚构&quot;真实用户&quot;的使用体验和效果反馈</li><li>不能伪造评论、点赞等社交证据</li></ul><p>风格上像素人拍的，和冒充素人说话，是两件事。前者是创意，后者是虚假广告。</p></div><h2 id="已知的方向" tabindex="-1">已知的方向 <a class="header-anchor" href="#已知的方向" aria-label="Permalink to &quot;已知的方向&quot;">​</a></h2><p>「不像广告」的视觉特征，大致是这几项的组合：</p><table tabindex="0"><thead><tr><th>特征</th><th>对应的 Prompt 方向</th></tr></thead><tbody><tr><td>手持晃动</td><td><code>手持拍摄，轻微晃动，不稳定</code></td></tr><tr><td>光线不完美</td><td><code>室内混合光源，色温不统一，轻微曝光不足</code></td></tr><tr><td>构图随意</td><td><code>随手拍，构图不居中，主体偏离画面中心</code></td></tr><tr><td>画质一般</td><td><code>手机拍摄，轻微噪点，压缩感</code></td></tr><tr><td>环境真实</td><td>背景里有杂物、没收拾的痕迹</td></tr><tr><td>表演不专业</td><td><code>素人，不看镜头，表情自然，没有摆拍</code></td></tr></tbody></table><p>核心逻辑：**把所有&quot;专业&quot;的参数反过来写。**浅景深改成全景深（手机的默认状态），侧逆光改成顶部的室内灯，干净背景改成有生活痕迹的背景。</p><h2 id="待填内容" tabindex="-1">待填内容 <a class="header-anchor" href="#待填内容" aria-label="Permalink to &quot;待填内容&quot;">​</a></h2><h3 id="基础-ugc-风格包" tabindex="-1">基础 UGC 风格包 <a class="header-anchor" href="#基础-ugc-风格包" aria-label="Permalink to &quot;基础 UGC 风格包&quot;">​</a></h3><ul><li>图片版：</li><li>视频版：</li><li>实测效果：</li></ul><h3 id="分场景变体" tabindex="-1">分场景变体 <a class="header-anchor" href="#分场景变体" aria-label="Permalink to &quot;分场景变体&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>Prompt 要点</th><th>效果</th></tr></thead><tbody><tr><td>开箱</td><td></td><td></td></tr><tr><td>使用记录</td><td></td><td></td></tr><tr><td>前后对比</td><td></td><td></td></tr><tr><td>出镜口播</td><td></td><td></td></tr></tbody></table><h3 id="度的把握" tabindex="-1">度的把握 <a class="header-anchor" href="#度的把握" aria-label="Permalink to &quot;度的把握&quot;">​</a></h3><p>「粗糙」和「劣质」之间有一条线，需要实测找到：</p><ul><li>加到什么程度显得真实：</li><li>超过什么程度显得廉价：</li></ul><h3 id="投放数据对比" tabindex="-1">投放数据对比 <a class="header-anchor" href="#投放数据对比" aria-label="Permalink to &quot;投放数据对比&quot;">​</a></h3><p>同一条创意，UGC 风格版和精致版的实际表现差异：</p><table tabindex="0"><thead><tr><th>项目</th><th>UGC 版</th><th>精致版</th><th>差异</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr></tbody></table><p>这个表格积累几轮之后，会成为很有价值的判断依据。相关方法见 <a href="/method/ab-testing">A/B 创意批量测试</a>。</p><hr><p>写作格式参考 <a href="/templates/prompt-card">Prompt 卡片模板</a>。</p>',25)])])}const b=a(o,[["render",l]]);export{u as __pageData,b as default};
